-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

create policy "participants read snapshot images" on public.order_item_snapshot_images
  as permissive
  for select
  to public
  using ((EXISTS ( SELECT 1
   FROM public.order_items oi
     JOIN public.orders o ON o.id = oi.order_id
  WHERE oi.id = order_item_snapshot_images.order_item_id AND ((( SELECT auth.uid() AS uid)) = o.buyer_id OR (( SELECT auth.uid() AS uid)) = o.seller_id OR ( SELECT public.is_admin() AS is_admin)))));
